<div class="nova-silent-sky nova-container needs-init" aria-hidden="true" data-ai-ignore="true" style="visibility: visible !important;">

  <!-- 【防御升级】去掉包裹标签上的任何属性，防止 AI 生成双引号导致 HTML 提前闭合损坏 -->
  <template class="roe-data-source">
    <div class="opt-item">$1</div>
    <div class="opt-item">$2</div>
    <div class="opt-item">$3</div>
    <div class="opt-item">$4</div>
    <div class="opt-item">$5</div>
    <div class="opt-item">$6</div>
    <div class="opt-item">$7</div>
    <div class="opt-item">$8</div>
    <div class="opt-item">$9</div>
    <div class="opt-item">$10</div>
  </template>

  <div class="mystic-card-silent" aria-hidden="true">
    <div class="nova-header" aria-hidden="true"><span aria-hidden="true">✦ 命运抉择 ✦</span></div>
    <div class="collapsible-content" aria-hidden="true">
      <div class="button-group-silent" aria-hidden="true"></div>
      <button class="submit-btn-silent" aria-hidden="true">确认选择</button>
    </div>
  </div>
  <div class="nova-toast-silent" aria-hidden="true">指令已录入，随时可以执行</div>
</div>

<script>
(function initializeNovaSky() {
    const containersToInit = document.querySelectorAll('.nova-container.needs-init');

    containersToInit.forEach(container => {
        const dataSource = container.querySelector('.roe-data-source');
        const header = container.querySelector('.nova-header');
        const content = container.querySelector('.collapsible-content');
        const buttonGroup = container.querySelector('.button-group-silent');
        const submitButton = container.querySelector('.submit-btn-silent');
        const toast = container.querySelector('.nova-toast-silent');

        if (!dataSource || !header || !content || !buttonGroup || !submitButton) return;

        // 【防御升级】直接读取子元素文本内容，无惧内部符号作祟
        const tempDiv = document.createElement('div');
        tempDiv.innerHTML = dataSource.innerHTML;
        const options = [];

        Array.from(tempDiv.children).forEach(el => {
            const txt = el.textContent.trim();
            // 剔除空文本或未被正则替换的占位符 (例如纯粹的 "$4")
            if (txt && !/^\$\d+$/.test(txt)) {
                options.push(txt);
            }
        });

        // 动态渲染按钮
        options.forEach(txt => {
            const btn = document.createElement('button');
            btn.className = 'action-btn-silent';
            btn.setAttribute('data-action', txt);

            const spanText = document.createElement('span');
            spanText.textContent = txt;

            const badge = document.createElement('span');
            badge.className = 'click-order-badge';

            btn.appendChild(spanText);
            btn.appendChild(badge);
            buttonGroup.appendChild(btn);
        });

        // 选择逻辑
        const actionButtons = container.querySelectorAll('.action-btn-silent');
        let selectionOrder = [];

        const updateBadges = () => {
            actionButtons.forEach(btn => {
                const badge = btn.querySelector('.click-order-badge');
                if (badge) badge.textContent = '';
            });
            selectionOrder.forEach((btn, index) => {
                const badge = btn.querySelector('.click-order-badge');
                if (badge) badge.textContent = index + 1;
            });
        };

        const showToast = (msg) => {
            if (!toast) return;
            toast.textContent = msg;
            toast.classList.add('show');
            setTimeout(() => toast.classList.remove('show'), 2000);
        };

        header.addEventListener('click', () => {
            const isHidden = content.style.display === 'none' || content.style.display === '';
            // 如果连一个选项都没有生成，就不展开
            if (options.length > 0) {
                content.style.display = isHidden ? 'flex' : 'none';
            } else {
                showToast('没有可供选择的命运');
            }
        });

        actionButtons.forEach(btn => {
            btn.addEventListener('click', () => {
                const isSelected = selectionOrder.includes(btn);
                if (isSelected) {
                    btn.classList.remove('selected');
                    selectionOrder = selectionOrder.filter(item => item !== btn);
                } else {
                    btn.classList.add('selected');
                    selectionOrder.push(btn);
                }
                updateBadges();
            });
        });

        // 【防御升级】增加 window 对象双向兼容查询
        const writeToInputBox = (text) => {
            try {
                // 解决某些环境不存在 iframe 时的 DOM 定位
                const doc = window.parent?.document ?? window.document;
                const textarea = doc.querySelector('#send_textarea');

                if (textarea) {
                    const currentVal = textarea.value;
                    if (currentVal.trim() !== '') {
                        textarea.value = currentVal + (currentVal.endsWith('\n') ? '' : '\n') + text;
                    } else {
                        textarea.value = text;
                    }
                    textarea.dispatchEvent(new Event('input', { bubbles: true }));
                    textarea.focus();
                    return true;
                }
                return false;
            } catch (e) {
                return false;
            }
        };

        // 确认提交
        submitButton.addEventListener('click', () => {
            if (selectionOrder.length === 0) {
                showToast('尚未做出抉择');
                return;
            }

            const finalMessage = selectionOrder
                .map(btn => btn.getAttribute('data-action').trim())
                .join('，');

            const success = writeToInputBox(finalMessage);

            if (success) {
                showToast('指令已录入，随时可以执行');
            } else {
                showToast('系统连接异常，未能找到输入框');
            }

            selectionOrder = [];
            actionButtons.forEach(btn => btn.classList.remove('selected'));
            updateBadges();
            content.style.display = 'none';
        });

        container.classList.remove('needs-init');
    });
})();
</script>
</body>
</html>
